item.aggregated_output:
        self._base_attr_map,
        self._is_exc,
        self._on_setattr,
        attrs_init=False,
    )

    def _attach_init(cls_dict, globs):
        init = globs["__init__"]
        init.__annotations__ = annotations
        cls_dict["__init__"] = self._add_method_dunders(init)

    self._script_snippets.append((script, globs, _attach_init))

    return self

def add_replace(self):
    # We create a local `evolve` proxy because it gets modified in place.
    def __replace__(*args, **changes):
        return evolve(*args, **changes)

    self._cls_dict["__replace__"] = self._add_method_dunders(__replace__)
    return self

def add_match_args(self):
    self._cls_dict["__match_args__"] = tuple(
        field.name
        for field in self._attrs
        if field.init and not field.kw_only
        builder.add_str()

    if props.added_eq:
        builder.add_eq()
    if props.added_ordering:
        builder.add_order()

    if not frozen:
        builder.add_setattr()

    if props.is_hashable:
        builder.add_hash()
    elif props.hashability is Hashability.UNHASHABLE:
        builder.make_unhashable()

    if props.added_init:
        builder.add_init()
    else:
        builder.add_attrs_init()
        if cache_hash:
            msg = "Invalid value for cache_hash.  To use hash caching, init must be True."
            raise TypeError(msg)

    if PY_3_13_PLUS and not _has_own_attribute(cls, "__replace__"):
        builder.add_replace()

    if match_args and not _has_own_attribute(cls, "__match_args__"):
        builder.add_match_args()

    return builder.build_class()

